window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[199]={"id":"199","numero":199,"titre":"Syndrome douloureux régional complexe","objectifs":[{"id":"199-1","rang":"A","rubrique":"Définition","titre":"Connaître la terminologie et la définition du syndrome douloureux régional complexe (SDRC)","contenu":"<p>Le <span class=\"kw-def\">syndrome douloureux régional complexe</span> (<span class=\"kw-def\">SDRC</span>, ou <span class=\"kw-def\">CRPS</span> pour <em>Complex Regional Pain Syndrome</em>, anciennement <span class=\"kw-def\">algodystrophie</span>) est un <span class=\"kw-def\">diagnostic clinique</span> et <span class=\"kw-alerte\">d'exclusion</span>, défini par l'<span class=\"kw-def\">IASP</span> (International Association for the Study of Pain) et <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de Budapest</span>.</p>\n      <p>Chaque mot du nom porte une idée :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Terme</th><th>Signification</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Syndrome</span></td><td>La définition est <span class=\"kw-clinique\">clinique</span> (pas de test pathognomonique)</td></tr>\n          <tr><td><span class=\"kw-def\">Douloureux</span></td><td>La <span class=\"kw-clinique\">douleur</span> est <strong>indispensable</strong> au diagnostic</td></tr>\n          <tr><td><span class=\"kw-def\">Régional</span></td><td>Extension possible des symptômes, parfois à <span class=\"kw-clinique\">tout un membre</span></td></tr>\n          <tr><td><span class=\"kw-def\">Complexe</span></td><td>Variabilité des symptômes dans leur <span class=\"kw-clinique\">localisation</span>, leur <span class=\"kw-clinique\">présentation</span> et dans le <span class=\"kw-clinique\">temps</span></td></tr>\n        </tbody>\n      </table>\n      <p>Tableau clinique : douleur <span class=\"kw-clinique\">régionale</span>, <span class=\"kw-clinique\">continue</span>, spontanée ou provoquée, paraissant <span class=\"kw-alerte\">disproportionnée</span> en intensité ou en durée par rapport à l'<span class=\"kw-clinique\">évolution</span> attendue de l'événement déclenchant ; associée de façon inconstante à des signes <span class=\"kw-clinique\">moteurs</span>, <span class=\"kw-clinique\">sensitifs</span>, <span class=\"kw-clinique\">sudomoteurs</span>, <span class=\"kw-clinique\">vasomoteurs</span> et <span class=\"kw-clinique\">trophiques</span>.</p>\n      <p>Deux types selon l'existence d'une <span class=\"kw-clinique\">lésion</span> nerveuse :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Type</th><th>Ancien nom</th><th>Fréquence</th><th>Lésion nerveuse</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">SDRC de type 1</span></td><td>Algodystrophie</td><td><span class=\"kw-chiffre\">90 %</span></td><td><strong>Absence</strong> de <span class=\"kw-clinique\">lésion</span> nerveuse périphérique patente ; ne correspond <span class=\"kw-alerte\">pas</span> à un territoire nerveux (tronculaire ou radiculaire)</td></tr>\n          <tr><td><span class=\"kw-def\">SDRC de type 2</span></td><td>Causalgie</td><td><span class=\"kw-chiffre\">10 %</span></td><td>Succède à une <span class=\"kw-alerte\">lésion nerveuse périphérique patente</span> ; la douleur peut suivre une systématisation tronculaire, mais l'extension régionale est possible</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"199-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence et la physiolopathologie du SDRC","contenu":"<p><strong><span class=\"kw-def\">Épidémiologie</span>.</strong></p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Paramètre</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Incidence annuelle</span> (type 1)</td><td>Faible : <span class=\"kw-chiffre\">5 à 25 / 100 000</span></td></tr>\n          <tr><td>Âge de début</td><td>Adulte à tout âge, pic entre <span class=\"kw-chiffre\">50-70 ans</span> ; exceptionnel chez l'enfant/adolescent</td></tr>\n          <tr><td>Sex-ratio</td><td>Prédominance féminine (<span class=\"kw-chiffre\">3 F / 1 H</span>), surtout en post-ménopause</td></tr>\n          <tr><td>Site le plus touché</td><td><strong>Rhumato :</strong> membre inférieur 2× plus touché que le supérieur<br><strong>MPR :</strong> membre supérieur le plus souvent touché</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-clinique\">Évolution</span></strong> non prévisible, <span class=\"kw-def\">pronostic</span> difficile à établir (prudence dans l'information du patient) :</p>\n      <ul>\n        <li>Spontanément <span class=\"kw-clinique\">favorable</span> dans <span class=\"kw-chiffre\">90 %</span> des cas, mais peut être prolongée (<span class=\"kw-chiffre\">12 à 24 mois</span>)</li>\n        <li><span class=\"kw-alerte\">Défavorable</span> dans <span class=\"kw-chiffre\">5-10 %</span> : persistance de <span class=\"kw-clinique\">douleurs</span> hyperalgiques invalidantes plusieurs années, <span class=\"kw-clinique\">troubles trophiques</span>, <span class=\"kw-clinique\">rétractions aponévrotiques</span></li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span></strong> — complexe et encore mal connue (d'où des traitements <span class=\"kw-alerte\">symptomatiques</span> plutôt que curatifs). Dysfonctionnements neurologiques étagés :</p>\n      <ul>\n        <li><strong>Dysfonction du <span class=\"kw-bio\">SNP</span> :</strong> <span class=\"kw-clinique\">inflammation neurogène</span> périphérique, dérèglement régional du <span class=\"kw-bio\">système nerveux végétatif</span></li>\n        <li><strong>Dysfonctions <span class=\"kw-bio\">médullaires</span> :</strong> dysfonctionnements sympathiques et sensitifs</li>\n        <li><strong>Dysfonction <span class=\"kw-bio\">cérébrale</span> :</strong> intégration anormale de la douleur, réorganisation de la représentation corticale du membre (sensitif et moteur) contribuant à la chronicisation</li>\n      </ul>\n      <p>Ces phénomènes médullaires et cérébraux sont considérés comme un exemple de <span class=\"kw-def\">plasticité maladaptative</span>. Une <span class=\"kw-clinique\">réaction inflammatoire disproportionnée</span> (libération de <span class=\"kw-bio\">tryptase</span>, <span class=\"kw-bio\">IL-6</span>, <span class=\"kw-bio\">TNF</span>) entraîne une sensibilisation des <span class=\"kw-bio\">nocicepteurs</span> périphériques et une inflammation neurogène en « tache d'huile », avec libération de <span class=\"kw-bio\">neuropeptides</span> excitateurs (<span class=\"kw-bio\">substance P</span>, <span class=\"kw-bio\">CGRP</span>) dans la corne postérieure médullaire. Le système immunitaire est aussi probablement impliqué.</p>","frequence":0},{"id":"199-3","rang":"A","rubrique":"Principales étiologies","titre":"Connaître les facteurs favorisants","contenu":"<div class=\"obj-callout\">\n        <strong>Un facteur déclenchant est très souvent retrouvé.</strong> Le SDRC fait suite à un événement local dans la majorité des cas, mais reste idiopathique dans environ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>10</span> %</span>.\n      </div>\n      <p><strong>Causes traumatiques</strong> — à l'origine de <span class=\"kw-chiffre\">50 %</span> des SDRC de type 1 :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Pas de relation</span> entre le déclenchement / la sévérité d'un SDRC et la sévérité du traumatisme</li>\n        <li>Délai d'apparition variable : quelques <span class=\"kw-chiffre\">jours</span> à quelques <span class=\"kw-chiffre\">semaines</span>, au maximum <span class=\"kw-chiffre\">≤ 3 mois</span></li>\n        <li>Facteurs favorisants : <span class=\"kw-etio\">chirurgie</span> (surtout <span class=\"kw-etio\">orthopédique</span>), <span class=\"kw-etio\">rééducation trop intensive</span> et douloureuse, <span class=\"kw-etio\">immobilisation prolongée</span> inappropriée</li>\n      </ul>\n      <p><strong>Autres étiologies / facteurs favorisants :</strong></p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Catégorie</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Neurologiques</span></td><td>AVC, SEP, tumeur cérébrale, HSA, SLA, atteinte nerveuse périphérique (ex. canal carpien), Parkinson</td></tr>\n          <tr><td><span class=\"kw-etio\">Cancérologiques</span></td><td><span class=\"kw-bio\">Envahissement</span> <span class=\"kw-etio\">néoplasique</span> locorégional, tumeur thoracique sous-jacente (SDRC 1 du membre supérieur), formes paranéoplasiques rares, leucémies, lymphomes</td></tr>\n          <tr><td><span class=\"kw-etio\">Cardiovasculaires</span></td><td>TVP, <span class=\"kw-clinique\">IDM</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Infectieuses</span></td><td><span class=\"kw-clinique\">Zona</span>, herpès, <span class=\"kw-clinique\">panaris</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Endocriniennes</span></td><td><span class=\"kw-etio\">Diabète</span>, hypertriglycéridémie, hyperuricémie, dysthyroïdies (hypothyroïdie)</td></tr>\n          <tr><td><span class=\"kw-etio\">Médicaments</span></td><td><span class=\"kw-ttt\">Barbituriques</span> (ex. phénobarbital), <span class=\"kw-ttt\">isoniazide</span>, <span class=\"kw-ttt\">iode radioactif</span>, <span class=\"kw-ttt\">antirétroviraux</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Obstétricales</span></td><td><strong>SDRC 1 de hanche</strong> de la <span class=\"kw-ci\">grossesse</span> (<span class=\"kw-chiffre\">3ᵉ trimestre</span>), post-partum</td></tr>\n          <tr><td><span class=\"kw-etio\">Ostéo-articulaires</span></td><td>Arthrite ; fragilité osseuse (Lobstein, ostéomalacie, hyperparathyroïdie, <span class=\"kw-etio\">diabète</span> phosphaté, <span class=\"kw-clinique\">anorexie</span> mentale)</td></tr>\n          <tr><td><span class=\"kw-etio\">Idiopathiques</span></td><td><span class=\"kw-chiffre\">10 %</span> des cas ; prédisposition <span class=\"kw-etio\">génétique</span> probable (<span class=\"kw-bio\">HLA DR13, DQ8, DR6, B62</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">\n        <strong>Piège — le psychisme n'est pas une cause.</strong> La <span class=\"kw-clinique\">symptomatologie anxiodépressive</span> souvent retrouvée est la <strong>conséquence</strong> du retentissement de la maladie, et <span class=\"kw-alerte\">ne peut pas être considérée comme un facteur déclenchant</span>. Il n'existe pas de personnalité prédisposante ; mais certaines conditions psychologiques (trouble thymique, anxiété, catastrophisme) participent à la <span class=\"kw-clinique\">chronicisation</span> de la douleur.\n      </div>","frequence":0},{"id":"199-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique devant une suspicion de SDRC","contenu":"<div class=\"obj-callout danger\">\n        <strong>Le SDRC est un diagnostic clinique et d'exclusion.</strong> Il n'existe <span class=\"kw-alerte\">aucun examen complémentaire pathognomonique</span> (tous peuvent être normaux) ; le diagnostic repose sur <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de Budapest</span> (IASP) après élimination des diagnostics différentiels.\n      </div>\n      <p><strong><span class=\"kw-def\">Critères diagnostiques</span> de Budapest</strong> — <span class=\"kw-clinique\">les</span> 4 conditions doivent être réunies :</p>\n      <ol>\n        <li><span class=\"kw-clinique\">Douleur permanente</span>, <span class=\"kw-alerte\">disproportionnée</span> par rapport à la cause</li>\n        <li><strong>Survenue initiale</strong> d'au moins <span class=\"kw-chiffre\">1 symptôme</span> dans <span class=\"kw-chiffre\">3 des 4</span> catégories ci-dessous</li>\n        <li><strong>Persistance lors de l'évaluation</strong> d'au moins <span class=\"kw-chiffre\">1 signe</span> dans <span class=\"kw-chiffre\">2 des 4</span> catégories</li>\n        <li><span class=\"kw-alerte\">Aucun autre diagnostic</span> n'explique mieux <span class=\"kw-clinique\">les</span> symptômes</li>\n      </ol>\n      <p><span class=\"kw-clinique\">Les</span> 4 catégories de symptômes / signes :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Catégorie</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Sensoriel</span></td><td><span class=\"kw-clinique\">Hyperesthésie</span>, <span class=\"kw-clinique\">hyperalgésie</span> et/ou <span class=\"kw-clinique\">allodynie</span> (mécanique statique/dynamique, thermique)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Vasomoteur</span></td><td>Modifications de <span class=\"kw-clinique\">couleur</span> (érythrocyanose, pâleur) et/ou de <span class=\"kw-clinique\">température</span> cutanée</td></tr>\n          <tr><td><span class=\"kw-clinique\">Sudation / Œdème</span></td><td>Modification de la <span class=\"kw-clinique\">sudation</span> et/ou apparition d'un <span class=\"kw-clinique\">œdème</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Moteur / Trophique</span></td><td><span class=\"kw-clinique\">Faiblesse</span>, <span class=\"kw-clinique\">tremblement</span>, <span class=\"kw-clinique\">dystonie</span> et/ou <span class=\"kw-clinique\">troubles trophiques</span> (poils, ongles, peau)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Caractéristiques de la douleur</strong> (clé du diagnostic) :</p>\n      <ul>\n        <li><strong>Topographie :</strong> <span class=\"kw-clinique\">régionale</span>, ne correspondant <span class=\"kw-alerte\">pas</span> à un territoire nerveux périphérique (sauf éventuellement SDRC 2)</li>\n        <li><strong>Horaire :</strong> <span class=\"kw-clinique\">permanente</span>, continue (surtout au début)</li>\n        <li><strong>Intensité :</strong> variable mais <span class=\"kw-alerte\">disproportionnée</span> en intensité/durée par rapport au facteur déclenchant ; <span class=\"kw-clinique\">impotence fonctionnelle</span> possible jusqu'à l'exclusion du membre du schéma corporel</li>\n        <li><strong>Facteurs aggravants :</strong> <span class=\"kw-clinique\">orthostatisme</span>, stimuli somatosensoriels</li>\n        <li><strong>Type :</strong> superficielle ou profonde (picotements, brûlures, fourmillements) ; souvent <span class=\"kw-clinique\">plurifactorielle</span></li>\n      </ul>\n      <div class=\"obj-callout warning\">\n        <strong>Diagnostics différentiels à éliminer.</strong> Pathologies non tumorales : <span class=\"kw-etio\">arthrite septique</span> / <span class=\"kw-etio\">ostéomyélite</span>, <span class=\"kw-etio\">arthrite microcristalline</span> (goutte, chondrocalcinose), <span class=\"kw-etio\">mono/oligo-arthrite rhumatismale</span>, contusion post-traumatique, <span class=\"kw-etio\">ostéonécrose</span> / ostéochondrite, <span class=\"kw-etio\">fracture sous-chondrale</span>, synovite villonodulaire. Pathologies tumorales : <span class=\"kw-etio\">tumeurs osseuses</span>, <span class=\"kw-etio\">métastases</span>, hémopathies malignes (myélome), <span class=\"kw-etio\">maladie de Paget</span>. Penser aussi : <span class=\"kw-alerte\">thrombophlébite</span>, <span class=\"kw-alerte\">syndrome inflammatoire</span> (infection), <span class=\"kw-alerte\">syndrome des loges</span> (antécédent de plâtre), déplacement secondaire de fracture.\n      </div>","frequence":3},{"id":"199-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les différentes formes cliniques","contenu":"<p><strong><span class=\"kw-clinique\">Évolution</span> typique en 3 phases</strong> (schéma classique, en réalité très variable) :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Phase</th><th>Délai / durée</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Phase chaude</span> (<span class=\"kw-etio\">inflammatoire</span>)</td>\n            <td>Début souvent <span class=\"kw-clinique\">brutal</span> dans <span class=\"kw-clinique\">les</span> suites du traumatisme ; <span class=\"kw-chiffre\">quelques jours à 6 mois</span></td>\n            <td>Tableau d'« <span class=\"kw-clinique\">arthrite sans arthrite</span> » : <span class=\"kw-clinique\">douleur</span> articulaire/péri-articulaire, <span class=\"kw-clinique\">impotence</span> importante, coloration <span class=\"kw-clinique\">érythrosique</span> (parfois érythrocyanosique), <span class=\"kw-clinique\">œdème</span>, raideur, <span class=\"kw-clinique\">chaleur locale</span>, <span class=\"kw-clinique\">hypersudation</span>. PEC dès cette phase avec <strong>antalgie efficace</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Phase froide</span></td>\n            <td>Inconstante, débute généralement au <span class=\"kw-chiffre\">4ᵉ mois</span> ; jusqu'à guérison vers <span class=\"kw-chiffre\">12-24 mois</span></td>\n            <td><span class=\"kw-clinique\">Troubles des phanères</span> ; <span class=\"kw-clinique\">troubles trophiques</span> (segment froid, peau pâle lisse atrophique, acrocyanose) ; <span class=\"kw-alerte\">rétractions capsulo-ligamentaires</span> (enraidissement progressif) ; douleurs permanentes ou à la mobilisation</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Phase atrophique</span> (séquellaire)</td>\n            <td>Tardive</td>\n            <td>SDRC non évolutif ; <span class=\"kw-alerte\">séquelles</span> trophiques et fonctionnelles fixées</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">\n        <strong>Présentation très variable.</strong> Possible <span class=\"kw-clinique\">phase froide d'emblée</span> (notamment chez l'enfant), phase purement chaude, alternance de phases, ou formes à signes vasomoteurs prédominants.\n      </div>\n      <p><strong>Formes topographiques remarquables :</strong></p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Syndrome épaule-main</span></td><td>Contexte : hémiplégie, post-<span class=\"kw-clinique\">IDM</span>, pathologie intrathoracique, barbituriques, traumatisme. Atteinte de l'<span class=\"kw-clinique\">épaule</span> (souvent avant la main) → <span class=\"kw-clinique\">capsulite rétractile</span> en quelques semaines/mois. <span class=\"kw-imagerie\">Scintigraphie</span> (non indispensable) : <span class=\"kw-imagerie\">hyperfixation bifocale</span> (main + épaule)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Capsulite rétractile</span></td><td>Forme localisée à l'épaule, souvent sur pathologie dégénérative ; peut évoluer vers une <span class=\"kw-alerte\">épaule gelée</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Membre inférieur</span></td><td>Cheville/pied (le plus fréquent au MI) ; genou souvent post-chirurgical (arthroscopie) ; <strong>hanche</strong> : contexte de <span class=\"kw-ci\">grossesse</span> (3ᵉ trimestre), « hanche douloureuse à <span class=\"kw-imagerie\">radiographie</span> normale », <span class=\"kw-imagerie\">IRM indispensable</span> pour éliminer ostéonécrose ou fracture trabéculaire</td></tr>\n          <tr><td>Autres</td><td>Formes <span class=\"kw-clinique\">récidivantes</span> (même site ou côté opposé), formes <span class=\"kw-clinique\">familiales</span> (susceptibilité <span class=\"kw-etio\">génétique</span>)</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"199-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens d’imagerie à demander devant une suspicion de SDRC","contenu":"<div class=\"obj-callout danger\">\n        <strong>Aucun examen n'est pathognomonique.</strong> Le diagnostic reste <span class=\"kw-alerte\">clinique</span> ; <span class=\"kw-clinique\">les</span> examens paracliniques servent à <strong>éliminer les diagnostics différentiels</strong> et peuvent tous être <span class=\"kw-alerte\">normaux</span>.\n      </div>\n      <ul>\n        <li><strong><span class=\"kw-bio\">Biologie</span> :</strong> aucune anomalie reconnue. Un <span class=\"kw-alerte\">syndrome inflammatoire biologique</span> doit faire évoquer un <strong>autre diagnostic</strong>. Liquide articulaire (si ponctionné) : <span class=\"kw-bio\">mécanique</span>.</li>\n        <li><strong><span class=\"kw-bio\">ENMG</span> :</strong> <span class=\"kw-clinique\">normal</span> dans le SDRC 1 ; localise la <span class=\"kw-clinique\">lésion</span> dans le SDRC 2.</li>\n      </ul>\n      <p><strong>Imagerie</strong> (aucune n'est systématique) :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Examen</th><th>Performance / délai</th><th>Anomalies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Radiographies</span> standards comparatives</td>\n            <td>Peu sensible, peu spécifique ; signes <strong>décalés</strong> de quelques semaines à <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> mois</span> par rapport à la clinique ; peuvent rester normales (surtout chez l'enfant)</td>\n            <td><span class=\"kw-alerte\">Interligne articulaire respecté</span> (pas de pincement, pas d'<span class=\"kw-clinique\">érosion</span>) ; <span class=\"kw-imagerie\">déminéralisation locorégionale</span> des 2 versants (« <span class=\"kw-imagerie\">ostéoporose pommelée</span> ») : hypertransparence puis déminéralisation mouchetée, parfois disparition de la trame et des corticales</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Scintigraphie osseuse</span> (non systématique)</td>\n            <td><span class=\"kw-bio\">Se 80 %</span>, <span class=\"kw-bio\">Sp 70-80 %</span> ; <strong>précède</strong> <span class=\"kw-clinique\">les</span> signes radiographiques (une scinti normale n'élimine pas)</td>\n            <td><span class=\"kw-imagerie\">Hyperfixation locorégionale</span> aux 3 temps (vasculaire, tissulaire, osseux), avec extension aux articulations de voisinage. Parfois <span class=\"kw-imagerie\">hypofixation</span> (enfant, adolescent, forme froide d'emblée, sous-utilisation du membre)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">IRM</span> (2ᵉ intention)</td>\n            <td><span class=\"kw-bio\">Se 90 %</span> mais <span class=\"kw-bio\">Sp 17 %</span> ; anomalies aussi précoces que la <span class=\"kw-imagerie\">scintigraphie</span> ; <span class=\"kw-alerte\">normale dans les formes froides d'emblée</span> (une <span class=\"kw-imagerie\">IRM</span> normale n'élimine pas)</td>\n            <td><span class=\"kw-imagerie\">Œdème médullaire régional</span> touchant plusieurs pièces osseuses ; signaux <span class=\"kw-imagerie\">HypoT1</span> rehaussé au gadolinium, <span class=\"kw-imagerie\">HyperT2</span> / T2 STIR / Fat-Sat. À la hanche : seule l'épiphyse fémorale supérieure est concernée</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-source\"><em>Sémiologie radio complétée depuis la fiche source (description texte ; aucune image disponible au build — figure à ajouter ultérieurement si Kevin fournit <span class=\"kw-clinique\">les</span> clichés).</em></p>","frequence":1},{"id":"199-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge d’un SDRC","contenu":"<div class=\"obj-callout\">\n        <strong>La prévention est la meilleure approche thérapeutique.</strong> Deux contextes fréquents permettent une prévention efficace.\n      </div>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Contexte</th><th>Mesures préventives</th></tr></thead>\n        <tbody>\n          <tr><td>Après fracture / <span class=\"kw-ttt\">chirurgie</span> orthopédique</td><td><span class=\"kw-ttt\">Vitamine C</span> pendant <span class=\"kw-chiffre\">50 jours</span> (efficacité prouvée dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">fractures du poignet</span>) ; PEC de la douleur péri-opératoire ; rééducation adaptée ; <span class=\"kw-alerte\">immobilisation la plus courte possible</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Lésion</span> neurologique centrale</td><td><span class=\"kw-clinique\">Bon positionnement articulaire</span> des articulations à risque (épaule, poignet, genou, pied) : coussins, écharpe, orthèses de positionnement, repose-pied adapté</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Principes de la prise en charge curative</strong> — traitement <span class=\"kw-alerte\">symptomatique</span> (limiter la douleur, préserver la mobilité, éviter <span class=\"kw-clinique\">les</span> séquelles), à débuter <span class=\"kw-alerte\">précocement</span> pour éviter l'exclusion fonctionnelle du membre :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Moyen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Antalgiques</span></td><td>Paliers <span class=\"kw-chiffre\">1, 2, 3</span> gradués selon l'intensité ; antiépileptiques / antidépresseurs si composante <span class=\"kw-clinique\">neuropathique</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Kinésithérapie</span></td><td>Précoce dès que le SDRC est probable : mobiliser, prévenir <span class=\"kw-clinique\">les</span> rétractions, drainer l'<span class=\"kw-clinique\">œdème</span>, éviter l'exclusion. Physiothérapie <span class=\"kw-ttt\">antalgique</span>, thermothérapie (chaud, froid, bains écossais), massages de <span class=\"kw-ttt\">drainage</span>, techniques de gain articulaire/musculaire, rééducation sensitive, imagerie motrice et <span class=\"kw-clinique\">thérapie miroir</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Ergothérapie</span></td><td>Si atteinte du <span class=\"kw-clinique\">membre supérieur</span> : réintégration fonctionnelle, autonomie</td></tr>\n          <tr><td>Dispositifs / neurostimulation</td><td>Orthèses, cannes (antalgie + préservation fonctionnelle) ; <span class=\"kw-ttt\">TENS</span> (théorie du portillon de Wall et Melzack) ; <span class=\"kw-ttt\">neurostimulation médullaire</span> dans <span class=\"kw-clinique\">les</span> formes très sévères</td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout danger\">\n        <strong>Le repos total est interdit.</strong> Une <span class=\"kw-ci\">immobilisation stricte</span> pérennise le SDRC 1. Seul un <span class=\"kw-clinique\">repos relatif</span> est indiqué en phase chaude (au MI : simuler le pas + bas de contention). La « règle de la non-douleur » doit être <span class=\"kw-alerte\">abandonnée</span> : ni trop, ni pas assez (<span class=\"kw-clinique\">les</span> deux extrêmes réveillent la douleur).\n      </div>\n      <div class=\"obj-callout warning\">\n        <strong>Médicaments — aucune AMM spécifique en France.</strong> <span class=\"kw-ttt\">Antalgiques</span> utilisables : <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">opioïdes faibles</span>, <span class=\"kw-ttt\">antiépileptiques / antidépresseurs</span> (si neuropathique). À <span class=\"kw-ci\">éviter sans avis spécialisé</span> : <span class=\"kw-ci\">AINS</span>, <span class=\"kw-ci\">corticoïdes</span>, <span class=\"kw-ci\">opioïdes majeurs</span>.\n      </div>","frequence":2}],"astuces":[],"liensGlobaux":[{"href":"https://www.lecofer.org/item-objectifs-0-20-0.php","label":"lecofer.org"},{"href":"https://radiopaedia.org/articles/complex-regional-pain-syndrome","label":"radiopaedia.org"}],"cards":[{"i":"353ad32a0d1a","n":199,"o":"199-1","u":"Définition","t":"Connaître la terminologie et la définition du syndrome douloureux régional complexe (SDRC)","q":"Quelles sont les caractéristiques distinctives entre le SDRC de type 1 et le SDRC de type 2 ?","a":"<ul><li>Le <strong>SDRC de type 1</strong> (anciennement algodystrophie) représente <strong>90 %</strong> des cas et se caractérise par l'<strong>absence de lésion nerveuse périphérique patente</strong>. La douleur ne correspond pas à un territoire nerveux spécifique (tronculaire ou radiculaire).</li><li>Le <strong>SDRC de type 2</strong> (anciennement causalgie) représente <strong>10 %</strong> des cas et fait suite à une <strong>lésion nerveuse périphérique patente</strong>. Bien que la douleur puisse suivre une systématisation tronculaire, une extension régionale est possible.</li></ul>"},{"i":"b0a987c495c7","n":199,"o":"199-1","u":"Définition","t":"Connaître la terminologie et la définition du syndrome douloureux régional complexe (SDRC)","q":"Comment définir le Syndrome Douloureux Régional Complexe (SDRC) selon les critères actuels ?","a":"<p>Le SDRC est un <strong>diagnostic clinique et d'exclusion</strong> caractérisé par une <strong>douleur régionale</strong>, continue, spontanée ou provoquée, <strong>disproportionnée</strong> par rapport à l'événement déclenchant. Il s'associe inconstamment à des signes moteurs, sensitifs, sudomoteurs, vasomoteurs et trophiques. Sa définition est basée sur les critères de <strong>Budapest</strong> et la terminologie de l'<strong>IASP</strong> (International Association for the Study of Pain).</p>"},{"i":"b47fb7fcb25e","n":199,"o":"199-1","u":"Définition","t":"Connaître la terminologie et la définition du syndrome douloureux régional complexe (SDRC)","q":"Quelle est la signification de chaque terme dans l'appellation \"Syndrome Douloureux Régional Complexe\" ?","a":"<ul><li><strong>Syndrome</strong> : La définition est <strong>clinique</strong>, sans test pathognomonique.</li><li><strong>Douloureux</strong> : La <strong>douleur</strong> est un élément indispensable au diagnostic.</li><li><strong>Régional</strong> : Il y a une extension possible des symptômes, parfois à un membre entier.</li><li><strong>Complexe</strong> : Il existe une <strong>variabilité</strong> des symptômes dans leur localisation, leur présentation et leur évolution temporelle.</li></ul>"},{"i":"63a35aff1d34","n":199,"o":"199-3","u":"Principales étiologies","t":"Connaître les facteurs favorisants","q":"Quels sont les facteurs favorisants traumatiques les plus fréquents du syndrome douloureux régional complexe (SDRC) ?","a":"<p>Les traumatismes sont à l'origine de <strong>50 % des SDRC de type 1</strong>. Ils se manifestent souvent après :</p><ul><li>Une <strong>chirurgie</strong> (particulièrement orthopédique).</li><li>Une <strong>rééducation trop intensive et douloureuse</strong>.</li><li>Une <strong>immobilisation prolongée inappropriée</strong>.</li></ul>"},{"i":"7ce9f9aeb45e","n":199,"o":"199-3","u":"Principales étiologies","t":"Connaître les facteurs favorisants","q":"Quelles sont les principales causes neurologiques et cancérologiques pouvant favoriser un syndrome douloureux régional complexe (SDRC) ?","a":"<p>Les causes neurologiques incluent :</p><ul><li><strong>AVC</strong>, <strong>SEP</strong>, <strong>tumeur cérébrale</strong>, <strong>HSA</strong>, <strong>SLA</strong>.</li><li>Des <strong>atteintes nerveuses périphériques</strong> (comme le canal carpien).</li><li>La maladie de <strong>Parkinson</strong>.</li></ul><p>Les causes cancérologiques comprennent :</p><ul><li>Un <strong>envahissement néoplasique locorégional</strong>.</li><li>Une <strong>tumeur thoracique sous-jacente</strong> (pouvant entraîner un SDRC 1 du membre supérieur).</li><li>Plus rarement, des formes paranéoplasiques, des <strong>leucémies</strong> et des <strong>lymphomes</strong>.</li></ul>"},{"i":"921340e34de1","n":199,"o":"199-3","u":"Principales étiologies","t":"Connaître les facteurs favorisants","q":"Le psychisme est-il une cause ou un facteur favorisant direct du syndrome douloureux régional complexe (SDRC) ?","a":"<p>Non, le psychisme n'est <strong>pas une cause directe</strong> du SDRC. La symptomatologie anxiodépressive fréquemment observée est une <strong>conséquence du retentissement de la maladie</strong>. Il n'existe pas de personnalité prédisposante, mais certaines conditions psychologiques (trouble thymique, anxiété, catastrophisme) peuvent participer à la <strong>chronicisation de la douleur</strong>.</p>"},{"i":"cfb523422293","n":199,"o":"199-3","u":"Principales étiologies","t":"Connaître les facteurs favorisants","q":"Quels sont les facteurs favorisants infectieux, cardiovasculaires, endocriniens et médicamenteux du syndrome douloureux régional complexe (SDRC) ?","a":"<p>Les facteurs favorisants sont :</p><ul><li><strong>Infectieux :</strong> <strong>Zona</strong>, herpès, panaris.</li><li><strong>Cardiovasculaires :</strong> <strong>TVP</strong> (thrombose veineuse profonde), <strong>IDM</strong> (infarctus du myocarde).</li><li><strong>Endocriniens :</strong> <strong>Diabète</strong>, hypertriglycéridémie, hyperuricémie, <strong>dysthyroïdies</strong> (particulièrement l'hypothyroïdie).</li><li><strong>Médicamenteux :</strong> <strong>Barbituriques</strong> (ex. phénobarbital), <strong>isoniazide</strong>, <strong>iode radioactif</strong>, antirétroviraux.</li></ul>"},{"i":"02a338d82b2b","n":199,"o":"199-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une suspicion de SDRC","q":"Comment est établi le diagnostic de SDRC (Syndrome Douloureux Régional Complexe) ?","a":"<p>Le diagnostic de SDRC est un <strong>diagnostic clinique et d'exclusion</strong>. Il repose sur les <strong>critères de Budapest</strong> (IASP) après élimination des diagnostics différentiels.</p>"},{"i":"0c494052a41c","n":199,"o":"199-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une suspicion de SDRC","q":"Quelles sont les quatre catégories de symptômes et de signes pris en compte dans les critères de Budapest pour le diagnostic de SDRC ?","a":"<ul><li><strong>Sensoriel</strong> : <strong>hyperesthésie</strong>, <strong>hyperalgésie</strong> et/ou <strong>allodynie</strong>.</li><li><strong>Vasomoteur</strong> : modifications de couleur (<strong>érythrocyanose</strong>, pâleur) et/ou de température cutanée.</li><li><strong>Sudation / Œdème</strong> : modification de la sudation et/ou apparition d'un œdème.</li><li><strong>Moteur / Trophique</strong> : <strong>faiblesse</strong>, tremblement, dystonie et/ou troubles trophiques (poils, ongles, peau).</li></ul>"},{"i":"a4daf785a5de","n":199,"o":"199-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une suspicion de SDRC","q":"Quelles sont les caractéristiques clés de la douleur évocatrice de SDRC ?","a":"<ul><li><strong>Topographie</strong> : <strong>régionale</strong>, ne correspondant pas à un territoire nerveux périphérique.</li><li><strong>Horaire</strong> : <strong>permanente</strong>, continue (surtout au début).</li><li><strong>Intensité</strong> : <strong>disproportionnée</strong> en intensité et/ou durée par rapport au facteur déclenchant.</li><li><strong>Facteurs aggravants</strong> : <strong>orthostatisme</strong>, stimuli somatosensoriels.</li><li><strong>Type</strong> : superficielle ou profonde (picotements, brûlures, fourmillements).</li></ul>"},{"i":"baec71314a77","n":199,"o":"199-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une suspicion de SDRC","q":"Quels sont les quatre critères indispensables de Budapest pour diagnostiquer un SDRC ?","a":"<ul><li>La <strong>douleur est permanente et disproportionnée</strong> par rapport à la cause initiale.</li><li>Il y a eu, à l'initiation, au moins <strong>1 symptôme dans 3 des 4 catégories</strong> de manifestations cliniques suivantes : sensoriel, vasomoteur, sudation/œdème, moteur/trophique.</li><li>Il persiste, lors de l'évaluation, au moins <strong>1 signe dans 2 des 4 catégories</strong> de manifestations cliniques.</li><li><strong>Aucun autre diagnostic n'explique mieux</strong> les symptômes.</li></ul>"},{"i":"fab9863439a8","n":199,"o":"199-4","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une suspicion de SDRC","q":"Quels sont les diagnostics différentiels majeurs à éliminer devant une suspicion de SDRC ?","a":"<p>Il faut éliminer des pathologies non tumorales (ex : <strong>arthrite septique</strong>, <strong>ostéomyélite</strong>, arthrite microcristalline, mono/oligo-arthrite rhumatismale, fracture sous-chondrale, ostéonécrose) et tumorales (ex : <strong>tumeurs osseuses</strong>, métastases, myélome, maladie de Paget). Il faut aussi penser à la <strong>thrombophlébite</strong>, au syndrome inflammatoire, au <strong>syndrome des loges</strong> ou au déplacement secondaire de fracture.</p>"}]};